import { topics, projects, news } from './data.js';
import { S,esc,icon,link,button,badge,photo,brand,header,footer,banner,tabs,field,select,filters,publicPage,fileLink,cardTitle } from './ui.js';
const newsItems=()=>S.news.length?S.news:news.map((n,i)=>({id:'n'+i,title:n[0],date:n[1],image:n[2],text:n[3]}));
const stories=()=>newsItems().slice(1).map(n=>`<a href="#/news-detail?id=${n.id}" data-item data-category="${esc(n.category||'Новости')}">${photo(n.image)}<div><small>${esc(n.date)} · Демо</small><h3>${esc(n.title)}</h3></div><span class="arrow-circle">→</span></a>`).join('');
const faq=['Кто может участвовать в конкурсе?','Сколько проектов можно подать?','Какие есть номинации?','Как проходит отборочный этап?','Как оформить проект?','Когда будут объявлены результаты?','Где можно задать дополнительный вопрос?'];
const faqAnswers=['Школьники 5–11 классов. При регистрации несовершеннолетнего необходимо согласие законного представителя.','Один активный исследовательский проект в текущем сезоне. Организатор может изменить лимит.','Экология, биология, география, технологии, история и культура народов Севера.','Участники проходят онлайн-тест и подают проект. Допущенные работы оценивают эксперты.','Используй шаблоны и загрузи исследование, презентацию и дополнительные материалы.','После завершения экспертизы и утверждения комиссией. Следи за новостями и уведомлениями.','Напиши организаторам через форму в разделе «Контакты».'];
export const publicPages={
 home:()=>`<main id="main"><section class="home-hero hero-scene">${header('home',true)}<div class="home-copy"><div class="eyebrow">Всероссийский конкурс для школьников</div><h1>Удивительная<br>и неизведанная</h1><span class="arctic-word">АРКТИКА</span><p class="lead">Большое путешествие начинается с любопытства.</p><p class="sublead">Изучай Север, проходи тест и представь свой проект.</p><div class="hero-actions">${link('participate','НАЧАТЬ ПУТЕШЕСТВИЕ <span class="arrow-circle">→</span>','btn white')}${link('submit','ПОДАТЬ ПРОЕКТ ↗')}</div><a class="scroll-cue" href="#route" data-action="scroll-route"><span>↓</span>ЛИСТАЙ ВНИЗ</a></div><div class="coordinates">78° N<br>015° E</div><button class="video-cta" data-action="video"><span>▶</span><span>ПОЧУВСТВУЙ АРКТИКУ<small>СМОТРЕТЬ ВИДЕО</small></span></button></section><section class="route-strip" id="route"><div><div class="eyebrow">Твой маршрут</div><h2>От первого открытия —<br>к своему исследованию</h2></div>${[['Изучай','Погружайся в уникальный мир Арктики. Открывай факты, природу и людей Севера.','explore'],['Пройди тест','Проверь свои знания и узнай больше о возможностях.','test-intro'],['Создай проект','Предложи свою идею и внеси вклад в изучение и сохранение Арктики.','submit']].map(([t,d,id],i)=>`<div class="route-step"><span>0${i+1}</span>${link(id,`<h3>${t}</h3>`)}<p>${d}</p></div>`).join('')}</section><section class="container home-news"><div class="section-heading"><h2>Новости</h2>${link('news','ВСЕ НОВОСТИ →','text-link')}</div><div class="news-mini-grid">${newsItems().slice(0,3).map(n=>`<a class="news-mini" href="#/news-detail?id=${n.id}">${photo(n.image)}<div><small>${esc(n.date)}</small><h3>${esc(n.title)}</h3><span class="arrow">→</span></div></a>`).join('')}</div></section><section class="container partners-strip"><div class="participant-count">${icon('users','large')}<div><strong>12 450</strong> ${badge('Демо')}<small style="display:block">участников со всей России</small></div></div><div><strong>Наши партнёры</strong></div>${['leaf','globe','cap','heart','trophy'].map(i=>`<div class="partner-logo">${icon(i)}<small>Логотип<br>Уточняется</small></div>`).join('')}</section></main>${footer()}`,
 about:()=>publicPage('about',banner('О конкурсе','Вдохновляем исследовать Арктику<br>и создавать проекты для её будущего.')+`<div class="container">${tabs(['Цели','Организатор','Номинации','Этапы','Награды'],0,'about')}<div class="columns three" data-about-panel><div><h2>Цели конкурса</h2><p>Развивать интерес школьников к изучению Арктики, поддерживать исследовательские инициативы и формировать ответственное отношение к природе и людям Севера.</p></div><div>${[['leaf','Популяризация знаний об Арктике'],['cap','Поддержка исследовательских и творческих проектов'],['users','Развитие сообщества юных исследователей'],['globe','Вклад в сохранение природы и культуры Севера']].map(([i,t])=>`<div class="feature">${icon(i,'large')}<span>${t}</span></div>`).join('')}</div><div class="card tinted"><h3>Организатор</h3><div class="feature">${icon('home','large')}<div>Организатор конкурса<br><strong>Уточняется</strong></div></div><p>Конкурс проводится при поддержке ведущих научных, образовательных и культурных организаций.</p><small>Информация будет обновлена.</small></div></div><div class="features-row">${[['Номинации','Исследовательские, творческие и прикладные проекты по темам Арктики.','Все номинации','archive','globe'],['Два этапа','Отборочный (онлайн) и финальный (защита проектов).','Как проходят этапы','participate','file'],['Награды','Дипломы, памятные призы и возможности участия в специальных мероприятиях.','Подробнее о наградах','achievements','trophy']].map(([t,d,l,id,i])=>`<div class="feature">${icon(i,'large')}<div><h3>${t}</h3><p>${d}</p>${link(id,l+' →','btn sm')}</div></div>`).join('')}</div><div class="field-actions" style="margin-top:25px">${fileLink('rules','Скачать положение (PDF)')}${link('rules','Читать положение (HTML) →','btn sm')}</div></div>`),
 history:()=>publicPage('history',banner('История конкурса','Люди, идеи и открытия, которые вдохновляют.')+`<div class="container">${tabs(['2023','2022','2021'],0,'history')}<div class="history-grid"><div><h2>Финал <span data-history-year>2023</span></h2><p>Более 4 200 школьников из 78 регионов России приняли участие в конкурсе. Исследовательские, творческие и прикладные проекты посвящены природе, людям и будущему Арктики.</p><div class="history-stats">${[['4 200','участников'],['78','регионов'],['312','проектов']].map(([n,l])=>`<div><strong>${n}</strong><small>${l} · Демо</small></div>`).join('')}</div>${button('Итоги года →','history-result','sm')}</div><div><div class="section-heading"><h3>Фотогалерея</h3>${link('media','Все фото →','text-link')}</div><div class="photo-gallery">${['ice','explorer','owl','aurora','ship','reindeer'].map(n=>`<button class="media-item" data-action="image" data-image="${n}">${photo(n,'Фотографии Арктики')}</button>`).join('')}</div><div class="section-heading" style="margin-top:20px"><h3>Победители <span data-history-year>2023</span> (Демо)</h3>${link('archive','Все победители →','text-link')}</div><div class="winners">${projects.slice(0,3).map(p=>`<a href="#/archive">${photo(p[3])}<div>${badge('1 место')}<strong>${esc(p[0])}</strong><small>${esc(p[4])}</small></div></a>`).join('')}</div></div></div></div>`),
 rules:()=>publicPage('rules',banner('Положение и FAQ','Всё, что нужно знать об участии в конкурсе.')+`<div class="container">${tabs(['Положение','Вопросы и ответы'],0,'rules')}<div class="faq-layout"><aside>${['Общие положения','Цели и задачи','Участники','Номинации','Этапы и сроки','Требования к проектам','Критерии оценки','Награды','Организационный комитет','Контакты'].map((t,i)=>`<a class="text-link" href="#rule-${i}" data-action="scroll-section" data-target="rule-${i}" style="display:block;font-size:11px">${i+1}. ${t}</a>`).join('')}</aside><article data-rules-doc><h2>Положение о конкурсе</h2><p><small>Версия 1.0 · Демонстрационный текст · PDF</small></p>${['Общие положения','Цели и задачи','Участники','Номинации','Этапы и сроки','Требования к проектам','Критерии оценки','Награды','Организационный комитет','Контакты'].map((t,i)=>`<section id="rule-${i}" style="margin:18px 0"><h3>${i+1}. ${t}</h3><p style="font-size:12px">${i===0?'Конкурс посвящён изучению удивительной и неизведанной Арктики. Участники исследуют природу, культуру и будущее Севера.':faqAnswers[i%faqAnswers.length]}</p></section>`).join('')}${fileLink('rules')}</article><aside><h3>Частые вопросы</h3><div style="margin-top:15px">${filters([['Все темы','Участие','Проект'],['Все этапы','Регистрация','Тест','Проект']])}</div>${faq.map((q,i)=>`<details class="faq-item" data-item><summary>${q}</summary><p>${faqAnswers[i]}</p></details>`).join('')}</aside></div></div>`),
 participate:()=>publicPage('participate',banner('Твой маршрут<br>в мир Арктики','Исследуй. Создавай. Представь.<br>Пройди все этапы и расскажи свою историю Арктики.',{tall:true,landscape:false,crumb:false,eyebrow:'Всероссийский конкурс для школьников'})+`<div class="container"><div class="progress-steps">${[['Регистрация','1–31 октября','Создай личный кабинет и заполни анкету участника.','register'],['Тестирование','1–15 ноября','Пройди онлайн-тест по теме Арктики.','test-intro'],['Проект','до 1 марта','Разработай и загрузи свой исследовательский проект.','submit'],['Защита','15–31 марта','Представь проект экспертному жюри онлайн.','defense']].map(([t,d,p,id],i)=>`<div class="progress-step ${i===0?'done':''}"><span>0${i+1}</span>${link(id,`<strong>${t}</strong>`)}<div class="mint-text">${d}</div><p>${p}</p></div>`).join('')}</div><div class="card" style="margin-top:30px;background:#f0efeb"><h3>Критерии оценки проекта</h3><div class="partner-options"><div><h2>100</h2>баллов</div>${[['Актуальность',20,'Значимость темы для Арктики.'],['Научная основа',25,'Качество исследования и источников.'],['Оригинальность',20,'Новизна идеи и подхода.'],['Практическая ценность',20,'Возможность применения результатов.']].map(([t,n,p])=>`<div><strong>${t}</strong><div class="mint-text">${n} баллов</div><p>${p}</p></div>`).join('')}</div><small>Презентация — 15 баллов. Даты и критерии показаны как демонстрационные.</small></div><div style="margin-top:25px">${link('register','Зарегистрироваться <span class="arrow-circle">→</span>','btn primary')}</div></div>`),
 documents:()=>publicPage('documents',banner('Шаблоны документов','Используй актуальные шаблоны для подготовки и оформления проекта.')+`<div class="container">${tabs(['Все документы','Для участника','Для родителей','Оформление проекта','Полезные материалы'],0,'documents')}<div class="document-list">${[['Анкета участника (образец)','Заполни анкету для регистрации на конкурсе.','Для участника'],['Согласие родителей (законных представителей)','Бланк согласия на участие несовершеннолетнего в конкурсе.','Для родителей'],['Титульный лист проекта','Шаблон титульного листа с требованиями к оформлению.','Оформление проекта'],['Структура исследовательского проекта','Рекомендуемая структура и содержание разделов.','Полезные материалы'],['Презентация проекта (шаблон)','Шаблон презентации для защиты проекта.','Оформление проекта']].map(([t,p,cat],i)=>`<div class="document-row" data-item data-category="${cat}"><span class="document-icon">${icon('file')}</span><div class="info"><h3>${t} ${i<2?badge('Обязательно'):''}</h3><p>${p}</p></div><small>PDF<br>Демо</small>${fileLink('template-'+i,'Скачать')}</div>`).join('')}</div></div>`),
 explore:()=>publicPage('explore',banner('Исследуй Арктику','Погружайся в уникальный мир Арктики. Выбирай тему и узнавай больше<br>о природе, людях и будущем Севера.')+`<div class="container"><div class="grid-cards topic-grid">${topics.map(([t,p,img],i)=>`<a class="photo-card" href="#/bear?topic=${i}">${photo(img,t)}<div class="photo-copy"><h3>${t}</h3><p>${p}</p></div><span class="arrow-circle">→</span></a>`).join('')}</div></div>`),
 bear:params=>{const index=Number(params.get('topic')||1),topic=topics[index]||topics[1],isBear=index===1;return publicPage('bear',banner(isBear?'Белый медведь':esc(topic[0]),isBear?'Символ Арктики, удивительный хищник и индикатор<br>состояния северной природы.':esc(topic[1]),{landscape:!isBear})+`<div class="container article-layout"><aside class="article-toc"><h3>Содержание</h3>${['Общая информация','Среда обитания','Питание','Поведение','Размножение','Угрозы','Как помочь','Интересные факты'].map((t,i)=>`<a href="#article-${i}" data-action="scroll-section" data-target="article-${i}">${i+1}. ${t}</a>`).join('')}</aside><article class="article-text">${['Общая информация','Среда обитания','Питание','Поведение','Размножение','Угрозы','Как помочь','Интересные факты'].map((t,i)=>`<section id="article-${i}"><h3><span class="mint-text">0${i+1}</span>　${t}</h3><p>${isBear?['Белый медведь (Ursus maritimus) — крупный хищник арктических широт. Он прекрасно приспособлен к жизни в суровых северных условиях: обладает густым мехом, слоем подкожного жира и отличными навыками плавания.','Белые медведи живут в арктических районах и зависят от морского льда, который служит площадкой для охоты.','Основная добыча — тюлени. Медведь использует лёд для поиска пищи.','Медведи способны преодолевать большие расстояния и хорошо плавают.','Медвежата рождаются в снежной берлоге и остаются с матерью в первые годы жизни.','Сокращение морского льда и загрязнение среды влияют на условия жизни полярного хищника.','Сохранение экосистем, ответственное потребление и поддержка исследований помогают защищать Арктику.','Белый медведь играет важную роль в арктических экосистемах.'][i]:'Арктика — уникальный регион, объединяющий природу, людей и научные открытия. Изучение этой темы помогает понять взаимосвязи северных экосистем и найти идеи для своего проекта.'}</p></section>`).join('')}<div class="card tinted"><div class="columns three"><div><small>Длина тела</small><strong style="display:block">2–3 м</strong></div><div><small>Масса</small><strong style="display:block">300–700 кг</strong></div><div><small>Материал</small><strong style="display:block">Демонстрационный</strong></div></div></div></article><aside class="article-aside"><h3>Видео по теме</h3><button class="media-item" data-action="video">${photo('bear','Белый медведь')}<span class="play">▶</span></button><h3>Белый медведь в дикой природе</h3><p>Уникальные кадры из жизни полярного хищника.</p><div class="card"><h3>Следующая статья</h3>${photo('iceberg')}${link('bear?topic=3','Климат и лёд →','text-link')}</div></aside></div>`);},
 media:()=>publicPage('media',banner('Медиатека','Фотографии и видео из экспедиций, природы<br>и жизни Арктики. Открывай, изучай, вдохновляйся.')+`<div class="container">${tabs(['Фотографии','Видео'],0,'media')}${filters([['Все годы','2025','2024','2023'],['Все экспедиции','Арктика','Баренцево море']])}<div class="media-grid">${['bear','iceberg','mountain','islands','aurora','ship','whale','ice'].map((n,i)=>`<button class="media-item" data-item data-action="${i===2||i===6?'video':'image'}" data-image="${n}" data-category="${i===2||i===6?'Видео':'Фотографии'}" data-meta="${2025-i%3}">${photo(n,topics[i%7][0])}${i===2||i===6?'<span class="play">▶</span>':''}</button>`).join('')}</div><p><small data-found>Найдено 8 материалов (демо)</small></p></div>`),
 archive:()=>{const items=archiveItems();return publicPage('archive',banner('Архив проектов','Изучай проекты участников, находи идеи<br>и вдохновляйся достижениями школьников.')+'<div class="container">'+filters([['Все номинации',...new Set(items.map(p=>p.nomination))],['Все годы',...new Set(items.map(p=>p.year))]])+'<div class="grid-cards">'+items.map(p=>'<a href="#/archive?id='+p.id+'" class="project-card" data-item data-category="'+esc(p.nomination)+'" data-meta="'+esc(p.year)+'" data-action="archive-detail" data-id="'+p.id+'">'+photo(p.image,p.name)+'<div class="project-copy">'+badge(p.sample?'Демо':'Опубликован')+'<h3>'+esc(p.name)+'</h3><span class="arrow-circle">→</span><p>'+esc(p.nomination)+'<br>'+esc(p.year)+'</p></div></a>').join('')+'</div></div>');},
 news:()=>{const n=newsItems()[0];return publicPage('news',banner('Новости','События, анонсы и итоги конкурса.<br>Следи за жизнью Арктики вместе с нами.')+`<div class="container">${tabs(['Новости','Анонсы','Итоги'],0,'news')}${filters()}<div class="columns asymmetric"><article class="news-feature" data-item data-category="Новости">${badge('Главная новость')}<small style="color:#dce4ea">${esc(n.date)} · Демо</small><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p><a href="#/news-detail?id=${n.id}" class="btn white">Читать подробнее →</a></article><div class="news-list">${stories()}</div></div></div>`);},
 'news-detail':params=>{const n=newsItems().find(n=>n.id===params.get('id'))||newsItems()[0];return publicPage('news-detail',`<section style="height:250px;background:url('assets/ship.webp') center/cover;padding:25px 60px">${link('news','← К новостям','btn white sm')}</section><div class="container columns asymmetric"><article><small>${esc(n.date)} · Демо</small> ${badge(n.category||'Новости')}<h1 style="font-size:44px;margin:15px 0">${esc(n.title)}</h1><p style="font-size:16px">${esc(n.text)}</p><p>Мы приглашаем школьников со всей России исследовать Север, представлять свои идеи и вносить вклад в изучение и сохранение уникального региона.</p><p>Участников ждут онлайн-лекции, консультации экспертов и возможность представить свой проект на финальной выставке.</p><p>Арктика — это место открытий, где наука, природа и люди создают будущее вместе. Присоединяйся!</p>${link('register','Принять участие →','btn mint')}</article><aside class="news-list"><h3 style="margin-bottom:20px">Похожие новости</h3>${stories()}</aside></div>`);},
 partners:()=>publicPage('partners',banner('Партнёрство<br>для больших<br>открытий','Поддержите новое поколение исследователей Арктики. Вместе мы создаём возможности для знаний, исследований и будущего Севера.',{tall:true,landscape:false,crumb:false,eyebrow:'Сотрудничество, которое вдохновляет'})+`<div class="container"><div class="partner-options"><div><h2>Как можно<br>сотрудничать</h2></div>${[['cap','Финансовая поддержка','Стипендии, призы, развитие конкурса.'],['users','Экспертиза и наставничество','Лекции, консультации, участие в жюри.'],['bell','Информационное партнёрство','Освещение, совместные проекты, мероприятия.'],['heart','Волонтёрство','Помощь в организации, сопровождение участников.']].map(([i,t,p])=>`<div>${icon(i,'large')}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div><div class="card media-kit"><div class="feature">${icon('file','large')}<div><h3>Скачать медиакит</h3><p>Презентация конкурса, аудитория, возможности партнёрства.</p></div></div>${fileLink('mediakit')}${link('contacts?topic=Партнёрство','Предложить сотрудничество →','btn mint')}</div></div>`),
 contacts:params=>publicPage('contacts',banner('Контакты','Будем рады ответить на ваши вопросы<br>о конкурсе, участии и партнёрстве.',{landscape:false,crumb:false,eyebrow:'Мы на связи'})+`<div class="container contact-grid"><div><h2>Организаторы</h2><p>Всероссийский конкурс для школьников<br>«Арктика: удивительная и неизведанная».</p><div class="contact-details">${[['mail','Email'],['phone','Телефон'],['pin','Адрес']].map(([i,t])=>`<div class="contact-item">${icon(i,'large')}<div><strong>${t}</strong><p>Уточняется</p></div></div>`).join('')}</div><h3>Мы в социальных сетях</h3><div class="columns" style="margin-top:22px"><div class="social-card"><span class="social-disc">ᴠκ</span><div>ВКонтакте<p>Сообщество уточняется</p></div></div><div class="social-card"><span class="social-disc">➤</span><div>Telegram<p>Канал уточняется</p></div></div></div></div><form data-form="contact"><h2 style="margin-bottom:25px">Напишите нам</h2><div class="form-grid">${field('Ваше имя *','name','','text','required maxlength="100"')}${field('Email *','email','','email','required') }<div class="full">${select('Тема обращения *','topic',['Участие в конкурсе','Проект','Партнёрство','Другой вопрос'],params.get('topic')||'')}</div><div class="full">${field('Сообщение *','message','','textarea','required maxlength="2000"')}</div></div><p class="form-error" role="alert"></p><button class="btn mint wide">Отправить сообщение →</button></form></div>`),
 login:()=>`<main class="auth-layout" id="main"><div class="auth-scene"><div class="auth-quote">БОЛЬШОЕ ПУТЕШЕСТВИЕ<br>НАЧИНАЕТСЯ ЗДЕСЬ</div></div><div class="auth-content">${brand()}<h1>Вход<br>в личный кабинет</h1><p>Продолжайте своё путешествие<br>в мир Арктики.</p><form data-form="login">${field('Email *','email','','email','required autocomplete="email" placeholder="Email"')}${field('Пароль *','password','','password','required autocomplete="current-password" placeholder="Пароль"')}<button type="button" class="forgot text-link" data-action="forgot">Забыли пароль?</button><p class="form-error" role="alert"></p><button class="btn primary wide">Войти →</button></form><div class="separator">или</div>${button('<span class="social-disc" style="width:25px;height:25px;font-size:12px">ᴠκ</span> Войти через VK ID','integration','wide')}<div class="auth-bottom">Ещё нет аккаунта? ${link('register','Зарегистрироваться')}</div>${button('Демонстрационные аккаунты','demo','wide sm')}</div></main>`,
 register:()=>`<main class="auth-layout register-layout" id="main"><aside class="register-side">${brand()}<div class="register-steps">${['Регистрация','Подтверждение email','Согласия','Завершение'].map((t,i)=>`<div class="register-step ${i===0?'active':''}"><span>${i+1}</span>${t}</div>`).join('')}</div></aside><div class="auth-content"><div class="columns"><h1>Регистрация</h1><p>Создайте аккаунт, чтобы участвовать в конкурсе, следить за новостями и возможностями.</p></div><form data-form="register"><p style="color:var(--ink)">Выберите свою роль</p><input type="hidden" name="role" value="participant"><div class="role-chooser">${[['participant','Участник','Школьник, который хочет исследовать Арктику','user'],['teacher','Педагог','Учитель или наставник участников','users']].map(([r,t,p,i])=>`<button type="button" data-action="register-role" data-role="${r}" class="role-card ${r==='participant'?'selected':''}">${icon(i,'large')}<div><strong>${t}</strong><small>${p}</small></div></button>`).join('')}</div><div class="form-grid">${field('Email *','email','','email','required autocomplete="email"')}${field('Пароль *','password','','password','required minlength="8" maxlength="128" autocomplete="new-password"')}${field('Повторите пароль *','repeat','','password','required autocomplete="new-password"')}<div>${field('Код подтверждения *','code','','text','required inputmode="numeric" maxlength="6"')}<button type="button" class="text-link" data-action="code">Получить код</button></div></div><label class="checkbox" data-parent-consent><input type="checkbox" name="parentConsent" required><span>Я — законный представитель участника (родитель/опекун) *<small>Подтверждаю согласие на участие моего ребёнка в конкурсе.</small></span></label><label class="checkbox"><input type="checkbox" name="consent" required><span>Согласие на обработку персональных данных *<small>Ознакомьтесь с ${link('rules','текстом согласия')}.</small></span></label><p class="form-error" role="alert"></p><button class="btn mint wide">Зарегистрироваться →</button></form><div class="auth-bottom">Уже есть аккаунт? ${link('login','Войти')}</div></div></main>`
};

export function archiveItems(){const items=projects.map((p,i)=>({id:'sample-'+i,name:p[0],nomination:p[1],year:p[2],image:p[3],author:p[4],sample:true}));for(const p of S.archive){if(!items.some(x=>x.name===p.name))items.push({...p,year:p.year||p.created?.slice(0,4)||'2026'});}return items;}
